#!/usr/bin/env bash
# Wide statements fail: the changed-rows join of a check-strategy snapshot hits Trino's limit on
# generated bytecode past ~140 columns, and a MERGE that updates every column of a wide Iceberg table
# fails with an internal error past ~325 columns.
set -uo pipefail
QUIRK=01-wide-merge
HERE="$(cd "$(dirname "$0")" && pwd)"
source "$HERE/../lib.sh"
title "Wide check join and wide MERGE"
MAXC=${MAXC:-400} ROWS=${ROWS:-1000}
gen() { python3 -I "$HERE/sql.py" "$@"; }
cleanup() { drop w_src w_tgt m_tgt; }
cleanup
section "setup: two Iceberg tables of $MAXC columns (7 types cycling) and $ROWS rows, values differing"
q_must "$(gen ctas "$MAXC" w_src "$(loc w_src)" 0 "$ROWS")"
q_must "$(gen ctas "$MAXC" w_tgt "$(loc w_tgt)" 1 "$ROWS")"
show_sql "$(gen ctas 3 w_src '<location>' 0 "$ROWS")"

# probe_join <columns> <style> / probe_merge <columns>: run one statement, set OK=1 on success
probe_join() { q "$(gen join "$1" w_src w_tgt "$2")"; OK=$([[ $Q_STATE == SUCCEEDED ]] && echo 1 || echo 0); report "$1"; }
probe_merge() {
  drop m_tgt; q_must "$(gen ctas "$1" m_tgt "$(loc m_tgt)" 1 "$ROWS")"
  q "$(gen merge "$1" w_src m_tgt)"; OK=$([[ $Q_STATE == SUCCEEDED ]] && echo 1 || echo 0); report "$1"
}
report() { printf '%4d columns: %s%s\n' "$1" "$Q_STATE" "${Q_REASON:+: ${Q_REASON:0:200}}"; [[ $OK == 0 ]] && LAST_ERROR=${Q_REASON:0:200}; }
# threshold <probe> <points...> -- <step> [style]: probe the points, then bisect between the last
# success and the first failure down to <step> columns. Sets PASS and FAIL (0 when none).
threshold() {
  local probe=$1; shift; local points=() step style lo=0 hi=0 mid
  while [[ $1 != -- ]]; do points+=("$1"); shift; done; step=$2 style=${3:-}
  for k in "${points[@]}"; do
    $probe "$k" $style
    if (( OK )); then lo=$k; else hi=$k; break; fi
  done
  while (( hi > 0 && hi - lo > step )); do
    mid=$(( (lo + hi) / 2 ))
    $probe "$mid" $style
    if (( OK )); then lo=$mid; else hi=$mid; fi
  done
  PASS=$lo FAIL=$hi
}

section "a. check-strategy join: ON s.id = t.id AND (<per-column change test> OR ...)"
expected "the join runs at any width; Trino compiles the join filter into one generated method, limited to 64 KB of bytecode by the JVM (Error compiling class / Method code too large)"
show_sql "$(gen join 2 w_src w_tgt dbt)"
LAST_ERROR=""
threshold probe_join 100 200 "$MAXC" -- 10 dbt
join_pass=$PASS join_fail=$FAIL join_error=$LAST_ERROR
actual "dbt-style test: works at $join_pass columns${join_fail:+, fails at $join_fail}"
show_sql "$(gen join 2 w_src w_tgt distinct)"
probe_join "$MAXC" distinct
distinct="IS DISTINCT FROM at $MAXC columns: $Q_STATE"
actual "$distinct"

section "b. MERGE updating every column of a wide Iceberg table (trinodb/trino#15848, fixed in Trino by #17342)"
expected "the MERGE runs; in Trino before the fix it failed on generated bytecode size"
show_sql "$(gen merge 2 w_src m_tgt)"
LAST_ERROR=""
threshold probe_merge 100 200 300 "$MAXC" -- 25
merge_pass=$PASS merge_fail=$FAIL merge_error=$LAST_ERROR
actual "works at $merge_pass columns$( (( merge_fail )) && echo ", fails at $merge_fail")"

cleanup
summary="check join (dbt style) ok at $join_pass cols$( (( join_fail )) && echo ", fails at $join_fail: $join_error"); $distinct; MERGE ok at $merge_pass cols$( (( merge_fail )) && echo ", fails at $merge_fail: $merge_error")"
if (( join_fail || merge_fail )); then verdict REPRODUCED "$summary"; else verdict "NOT REPRODUCED" "$summary"; fi
